import {readFileSync} from 'node:fs';
import vm from 'node:vm';
const {S,F,T,validate}=vm.runInNewContext(["core/finance.js","core/planning.js","core/trucking.js","core/mechanic.js","core/occupations.js","core/accounting.js","core/scanner.js"].map(p=>readFileSync(p,'utf8')).join('\n')+';({S:Scan,F:Finance,T:Trucking,validate})',{structuredClone});
function run(S,F,T,validate){let n=0;const eq=(a,b)=>{if(a!==b)throw Error('Expected '+b+' got '+a);n++};const throws=fn=>{let yes=false;try{fn()}catch{yes=true}eq(yes,true)};let i=0;const id=()=> 'test-'+(++i);
const sample='Vendor: Sample Parts\nDate: 2026-11-20\nOil filter 20.00\nBrake pad 30.00\nSubtotal 50.00\nSales tax 4.00\nTotal 54.00';const x=S.receipt(sample,[],'mechanic');eq(x.vendor,'Sample Parts');eq(x.date,'2026-11-20');eq(x.total,'54.00');eq(x.tax,'4.00');eq(x.items.length,2);eq(x.category,'Parts purchased');eq(x.warnings.length,0);eq(S.receipt(sample+'\nTotal 99.00').total,'');eq(S.receipt('Date: 2026-02-30\nTotal 4.00').date,'');eq(S.receipt('Vendor: Sample\nTotal 1.00').tax,'');eq(S.receipt(sample.replace('Total 54.00','Total 55.00')).warnings.length,1);
const s='Carrier: Sample Carrier\nSettlement # A123\nDate: 2026-11-20\nLinehaul 1000.00\nFuel surcharge 200.00\nFuel purchase -300.00\nFuel reimbursement 12.00\nDEF -10.00\nTruck payment -100.00\nInsurance -40.00\nMaintenance escrow -50.00\nGross revenue 1212.00\nTotal deductions 500.00\nNet payment 712.00';const v=S.settlement(s,'',[],[]);eq(v.carrier,'Sample Carrier');eq(v.number,'A123');eq(v.lines.length,8);eq(v.lines[3].category,'Fuel reimbursement');eq(v.lines[4].category,'DEF');eq(v.net,'712.00');eq(T.settlement({...v,truck:'Unit 1'}).difference,0);eq(T.settlement({...v,truck:'Unit 1'}).deductions,50000);eq(S.settlement(s.replace('Fuel reimbursement','Tractor Fuel Purchase 1'),'Sample Carrier',[{carrier:'Sample Carrier',match:'tractor fuel purchase 1',category:'Fuel reimbursement',classification:'revenue'}]).lines[3].classification,'revenue');eq(S.settlement(s.replace('DEF -10.00','Mystery -10.00')).lines[4].uncertain,true);eq(S.settlement(s.replace('Net payment 712.00','Net payment 713.00')).net,'713.00');
const p={job:'mechanic',scanner:S.blank(),profile:{},bills:[],operating:{},goals:{}},doc={name:'sample.png',data:'data:image/png;base64,abc=',type:'image/png',hash:'hash1'},reviewed={...x,reviewed:true};const out=S.postReceipt(reviewed,doc,p,[],[],id);eq(validate(out.rows).length,1);eq(F.total(out.rows).expense,5400);eq(out.record.tax,400);eq(out.profile.scanner.receipts[0].document.data,doc.data);eq(p.scanner.receipts.length,0);throws(()=>S.postReceipt({...reviewed,reviewed:false},doc,p,[],[],id));throws(()=>S.postReceipt(reviewed,doc,out.profile,out.rows,out.rows,id));throws(()=>S.postReceipt(reviewed,{...doc,hash:'hash2',data:'other'},p,out.rows,out.rows,id));const linked=S.postReceipt({...reviewed,link:out.rows[0].id},{...doc,hash:'hash2',data:'other'},p,out.rows,out.rows,id);eq(linked.rows.length,1);eq(linked.record.ledgerId,out.rows[0].id);const tr={job:'truck',trucking:{...T.blank(),trucks:[{name:'Unit 1'}]}};const saved=S.settlementDraft({...v,truck:'Unit 1'},doc,tr,[],id);eq(saved.trucking.settlements[0].posted,false);eq(saved.trucking.settlements[0].scanStatus,'review-required');eq(tr.trucking.settlements.length,0);throws(()=>S.settlementDraft({...v,truck:'Unit 1'},doc,saved,[],id));const before=JSON.stringify(out.rows),report=S.insights(out.profile,out.rows,'2026-11-01','2026-11-30','2026-10-01','2026-10-31');eq(report.now.expense,5400);eq(report.missing.length,0);eq(report.changes[0].change,5400);eq(JSON.stringify(out.rows),before);return n}
